/*
 * Memory
 *   Buffers belong to the caller.  The Rust allocations a caller holds are
 *   the objects of the _new() functions, each released with its _free():
 *   a Sv2FfiNoise per connection, and in the channels API an allocator
 *   and a channel object per channel, which keeps the jobs it is given.
 *   Nothing here keeps a pointer the caller passed in after returning.
 *
 * Return values
 *   SV2_FFI_OK (0), a byte count where documented, SV2_FFI_NEED_MORE from
 *   sv2_ffi_noise_try_decode(), or a negative SV2_FFI_ERR_* code.  The
 *   values are part of the API.
 *
 * Panics
 *   None reaches the caller.  A panic inside the library or the crates is
 *   caught and returned as SV2_FFI_ERR_INTERNAL (NULL from a constructor);
 *   the object the call was made on must then be freed, not used again.
 *
 * Threads
 *   Objects share no state, except an allocator and the channels opened
 *   from it.  Each object, an allocator and its channels counting as one,
 *   is used by one thread at a time and may move to another thread between
 *   calls.  That holds for a Sv2FfiNoise's encode and try_decode too: an
 *   error in either ends the whole session.
 *
 * Messages
 *   A Noise session takes and hands out whole messages; the caller reads
 *   and writes its own socket and never sees a frame header.
 *
 *   sv2_ffi_noise_encode(Sv2FfiNoise *n, const Sv2FfiMessage *m,
 *                        uint8_t *out, uint32_t cap)
 *     encodes the record in m, with the message type and the channel_msg
 *     bit mining_sv2 or common_messages_sv2 assigns, and encrypts it into
 *     out, ready to send.  sv2_ffi_noise_encoded_size(m) is the size.
 *     Byte fields of m are read only during the call.
 *
 *   sv2_ffi_noise_try_decode(Sv2FfiNoise *n, const uint8_t *in,
 *                            uint32_t in_len, uint32_t *consumed,
 *                            Sv2FfiMessage *out)
 *     takes whatever bytes arrived and returns the next message, or
 *     SV2_FFI_NEED_MORE.  Byte fields of out point into the frame the
 *     session keeps, valid until its next try_decode or its free.
 *
 *   All pointers must be valid for the sizes given; NULL where a value is
 *   required returns SV2_FFI_ERR_INVALID.
 */

// Success
#define SV2_FFI_OK 0

// `sv2_ffi_noise_try_decode()`: more input is needed
#define SV2_FFI_NEED_MORE 1

// A frame ended before the message it holds did
#define SV2_FFI_ERR_TRUNCATED -1

// Output buffer too small
#define SV2_FFI_ERR_OVERFLOW -2

// Malformed or out of spec value, or a NULL argument
